<script setup>import{onMounted,ref}from'vue';import api from '../services/api';const items=ref([]),error=ref('');onMounted(async()=>{try{items.value=(await api.get('/audit-logs')).data.data.data}catch(e){error.value=e.response?.data?.message||'অডিট লগ লোড করা যায়নি।'}})</script><template><section><div class="page-heading"><div><p class="eyebrow">SECURITY HISTORY</p><h2>অডিট লগ</h2><p>গুরুত্বপূর্ণ প্রশাসনিক পরিবর্তনের ইতিহাস।</p></div></div><p v-if="error" class="error">{{error}}</p><div class="table-card"><table><thead><tr><th>সময়</th><th>ব্যবহারকারী</th><th>ইভেন্ট</th><th>রেকর্ড</th><th>IP</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{new Date(item.created_at).toLocaleString()}}</td><td>{{item.user?.name||'System'}}</td><td>{{item.event}}</td><td>{{item.subject_type?`${item.subject_type.split('\\').pop()} #${item.subject_id}`:'—'}}</td><td>{{item.ip_address||'—'}}</td></tr><tr v-if="!items.length"><td colspan="5" class="empty">এখনও কোনো অডিট রেকর্ড নেই।</td></tr></tbody></table></div></section></template>
